def waysAtMostKCoins(coins, amount, k):
    MOD = 1000000007
    ways = [[0] * (amount + 1) for _ in range(k + 1)]
    ways[0][0] = 1
    for c in coins:
        for j in range(1, k + 1):
            prev = ways[j - 1]
            cur = ways[j]
            for s in range(c, amount + 1):
                if prev[s - c]:
                    cur[s] = (cur[s] + prev[s - c]) % MOD
    return sum(ways[j][amount] for j in range(k + 1)) % MOD
